using JasperFx.Events;                 // IEvent<T>
using Marten;                          // IDocumentOperations
using Marten.Events.Projections;       // EventProjection
using Campaigns.Contracts;

namespace Campaigns.Views;

/// <summary>
/// Context: campaigns. Slice: delivery-log. Fed by MessageQueued.
///
/// RECIPE 3: an EventProjection — the only one of the six that is NOT an aggregation.
///
/// Every other recipe folds many events into one row. This one takes one event and writes MANY rows: a
/// MessageQueued carrying five recipients produces five DeliveryLog documents in one go. No
/// <c>Identity&lt;T&gt;</c> can express that, because Identity maps an event to exactly one row, and
/// <c>Identities&lt;T&gt;</c> only helps when the ids are already in the payload as ids.
///
/// The model said as much before any code existed: <c>identity="messageId, recipient"</c> on a view fed by
/// an event whose grain is <c>messageId</c> alone. A view finer-grained than every event feeding it is the
/// tell for this recipe.
///
/// TWO THINGS THAT ARE ONLY TRUE OF EventProjection:
///
/// 1. <c>Options.DeleteViewTypeOnTeardown&lt;T&gt;()</c> is MANDATORY, and forgetting it is silent. Because
///    this projection writes through ad-hoc <c>ops.Store</c> calls, Marten cannot infer which document
///    type it produces and therefore will not wipe the table on a rebuild. The rows survive, the rebuild
///    re-upserts over them, and nothing complains — until a bulk-copy rebuild hits a duplicate key. Every
///    aggregation recipe gets this for free from its declared view type.
/// 2. The document id is ours to compose. <c>Key</c> exists so the tests and any reader agree on the same
///    string, rather than two places both formatting "{messageId}:{recipient}" and hoping.
/// </summary>
public sealed record DeliveryLog
{
    public string Id { get; init; } = default!;

    public Guid MessageId { get; init; }

    public Guid CampaignId { get; init; }

    /// <summary>
    /// Computed from recipients — a FAN-OUT, not a rename. mappings="recipient=recipients" would have
    /// claimed a string[] *is* a string, which the checker rejects as mapping-crosses-types.
    /// </summary>
    public string Recipient { get; init; } = default!;

    public string Subject { get; init; } = default!;

    public DateTimeOffset QueuedAt { get; init; }
}

/// <summary>
/// Registered Inline in ViewRegistrations: nothing about this recipe forces Async. It writes documents in
/// the append's own transaction exactly like a single-stream projection does.
/// </summary>
public sealed partial class DeliveryLogProjection : EventProjection
{
    public DeliveryLogProjection()
    {
        // See point 1 above. Without this a rebuild leaves the old rows in place.
        Options.DeleteViewTypeOnTeardown<DeliveryLog>();
    }

    /// <summary>One row per recipient, all of them from one event.</summary>
    public void Project(IEvent<MessageQueued> e, IDocumentOperations ops)
    {
        foreach (var recipient in e.Data.Recipients)
        {
            ops.Store(new DeliveryLog
            {
                Id = Key(e.Data.MessageId, recipient),
                MessageId = e.Data.MessageId,
                CampaignId = e.Data.CampaignId,
                Recipient = recipient,
                Subject = e.Data.Subject,
                QueuedAt = e.Data.QueuedAt,
            });
        }
    }

    /// <summary>The composite key, in one place so a reader and this projection cannot disagree.</summary>
    public static string Key(Guid messageId, string recipient) => $"{messageId}:{recipient}";
}
